function icon(name, cls) {
  if (name === 'angel' || name === 'demon' || name === 'human') return emblem(name, cls);
  return '<svg class="ico ' + (cls || '') + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + (ICONS[name] || '') + '</svg>';
}
function emblem(name, cls) {
  var e = EMBLEMS[name]; if (!e) return '';
  var g = e.g;
  if ((cls || '').indexOf('drawn') >= 0) g = g.replace(/<path /g, '<path pathLength="1" ');
  return '<svg class="emb ' + (cls || '') + '" viewBox="' + e.vb + '" fill="currentColor" aria-hidden="true">' + g + '</svg>';
}
function logoMark(cls) {
  var s = '', x = 0;
  ['魔','天','楼'].forEach(function (c) { s += '<path transform="translate(' + x + ',0)" d="' + LOGO_GLYPHS[c] + '"/>'; x += 1000; });
  return '<svg class="wordmark ' + (cls || '') + '" viewBox="0 -20 3000 1040" fill="currentColor" role="img" aria-label="魔天楼">' + s + '</svg>';
}

