function logoSvg(cls, fill) {
  var g = LOGO.g.replace(/currentColor/g, fill || 'currentColor');
  if ((cls || '').indexOf('drawn') >= 0) g = g.replace(/<path /g, '<path pathLength="1" ');
  return '<svg class="logo ' + (cls || '') + '" viewBox="' + LOGO.vb + '" role="img" aria-label="魔天楼">' + g + '</svg>';
}
